    async function bootPreloadedTopologies() {
      // 1. Check for Preloaded Session (computed from Python)
      if (window.PRELOADED_SESSION) {
        console.log('Preloaded session detected.');

        // Show strain analysis if present
        if (window.PRELOADED_SESSION.strainAnalysis) {
          const strainToggle = document.getElementById('strain-toggle');
          const strainCard = document.getElementById('strain-card');
          const strainClose = document.getElementById('strain-close');
          const strainContent = document.getElementById('strain-content');

          if (strainToggle && strainCard && strainClose && strainContent) {
            strainToggle.classList.remove('hidden');
            strainContent.textContent = window.PRELOADED_SESSION.strainAnalysis;

            strainToggle.addEventListener('click', () => {
              // Hide node detail card to prevent overlap
              const detailCard = document.getElementById('detail-card');
              if (detailCard) detailCard.classList.remove('visible');

              strainCard.classList.add('visible');
            });

            strainClose.addEventListener('click', () => {
              strainCard.classList.remove('visible');
            });
          }
        }

        restoreFromCache(window.PRELOADED_SESSION);
        return;
      }

      // 2. Check for Preloaded Notes (runs browser pipeline automatically)
      if (window.PRELOADED_NOTES && window.PRELOADED_NOTES.length > 0) {
        console.log('Preloaded notes detected. Running pipeline...');
        const apiKey = window.PRELOADED_API_KEY || getSavedApiKey();
        if (apiKey) {
          const apiKeyInput = document.getElementById('api-key-input');
          if (apiKeyInput) apiKeyInput.value = apiKey;
          document.getElementById('setup').classList.add('hidden');
          document.getElementById('main').classList.remove('hidden');
          document.getElementById('reanalyze-btn').classList.remove('hidden');
          const fp = 'preloaded::' + Date.now();
          runPipeline(window.PRELOADED_NOTES, apiKey, fp);
        } else {
          // No API key - let them type it and run with preloaded notes
          const setupStatus = document.getElementById('setup-status');
          if (setupStatus) setupStatus.textContent = 'LOADED NOTES FROM CLI. ENTER GEMINI API KEY TO RUN.';
          const pickBtn = document.getElementById('pick-folder-btn');
          if (pickBtn) {
            pickBtn.textContent = 'RUN WITH PRELOADED NOTES';
            const newPickBtn = pickBtn.cloneNode(true);
            pickBtn.replaceWith(newPickBtn);
            newPickBtn.addEventListener('click', () => {
              const apiKeyInput = document.getElementById('api-key-input');
              const key = apiKeyInput ? apiKeyInput.value.trim() : '';
              if (!key) return;
              saveApiKey(key);
              document.getElementById('setup').classList.add('hidden');
              document.getElementById('main').classList.remove('hidden');
              runPipeline(window.PRELOADED_NOTES, key, 'preloaded::' + Date.now());
            });
          }
        }
      }
    }

    window.addEventListener('DOMContentLoaded', () => {
      bootPreloadedTopologies();
    });

    // (label-toggle and config panel removed from release build)
  </script>

</body>

